function validate([num]) {
  if (typeof num !== 'string' || num.length < 1 || num.length > 1000) return 'num needs 1 to 1000 digits.';
  if (!/^[0-9]+$/.test(num)) return 'num may contain only digits.';
  if (num[0] === '0') return 'num is a positive integer without leading zeros.';
  return null;
}

