function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'small' ? pick(1, 12) : pick(900, 1000);
  const zeroChance = [0.1, 0.5, 0.9][pick(0, 2)];
  let num = String(pick(1, 9));
  while (num.length < n) num += rand() < zeroChance ? '0' : String(pick(0, 9));
  if (rand() < 0.5) {
    // Force a run of trailing zeros of random length.
    const zeros = pick(1, n - 1 || 1);
    num = num.slice(0, Math.max(1, n - zeros)) + '0'.repeat(n - Math.max(1, n - zeros));
  }
  return [num];
}
